mapper.update:
UPDATE video_status_outbox
SET status = 1,
    sending_at = #{sendingAt},
    lease_token = #{leaseToken}
WHERE id = #{id}
  AND status = 0

UPDATE video_status_outbox
SET status = 0,
    retry_count = retry_count + 1,
    next_retry_at = #{nextRetryAt},
    sending_at = NULL,
    lease_token = NULL,
    last_error = #{lastError}
WHERE event_id = #{eventId}
  AND status = 1
  AND lease_token = #{leaseToken}

UPDATE video_status_outbox
SET status = 3,
    retry_count = retry_count + 1,
    sending_at = NULL,
    lease_token = NULL,
    last_error = #{lastError}
WHERE event_id = #{eventId}
  AND status = 1
  AND lease_token = #{leaseToken}
